from lib import *
S = SS('k85')
F1 = [['--as=alice', '按 alice 的权限鉴权'], ['绑定 view 之前', 'Forbidden'], ['绑定之后', '成功;别的命名空间仍 Forbidden'], ['--as-group 单独写', '被 kubectl 拒绝']]
F2 = [['caller(只有 view)', '自己可读 pods'], ['--as=alice', 'Forbidden(无 impersonate)'], ['授予 impersonate users [alice]', '成功'], ['--as=bob / system:masters 组', 'Forbidden']]
F3 = [['caller 自己 edit', '能读 secrets'], ['caller 模拟 alice', '不能读 secrets'], ['结论', '模拟后只剩 alice 的权限']]
PANELS = [('f', 'flow', '模拟'), ('t', 'term', '实测输出'), ('kv', 'kv', '要点')]
steps = [
    step("管理员 kubectl get pods --as=alice:alice 没有任何权限,返回 Forbidden: User \"alice\" cannot list resource \"pods\" …;给 alice 绑定 view 之后成功,访问 default 命名空间仍是 Forbidden。kubectl auth whoami --as=alice --as-group=dev --as-group=ops 得到 username=alice、groups=['dev','ops','system:authenticated'](服务端补上 system:authenticated);加 --as-uid=uid-123 --as-user-extra=scopes=read 得到对应的 uid 和 extra。只写 --as-group 不写 --as 会被 kubectl 直接拒绝(without impersonating a user)。", f=fl(F1, cur=[0], mark=[3], done=[1, 2]), t=tl(S(1), mark=lidx(S(1), '--as=alice(alice 没有任何权限)', '只写 --as-group'), done=lidx(S(1), '绑定 view 之后', 'auth whoami')), kv=KV([['--as', '请求头 Impersonate-User,服务端按它鉴权'], ['groups', '自动补 system:authenticated'], ['必须带 --as', '光写组或 uid 不行']], ['--as'])),
    step("ServiceAccount caller(只有 view)自己读 pods 没问题;加 --as=alice 被拒:cannot impersonate-on:user-info:list resource \"pods\"(消息里的 verb 是 impersonate-on:user-info:list)。给它一条 impersonate users(resourceNames: [alice])的权限后,--as=alice 成功;换成 --as=bob 被拒:users \"bob\" is forbidden … cannot impersonate resource \"users\";--as=alice --as-group=system:masters 也被拒:groups \"system:masters\" is forbidden — 组要单独授权。模拟成功时 whoami 看到的用户名是 alice,caller 自己的身份被替换而不是叠加。", f=fl(F2, cur=[1, 2], mark=[3], done=[0]), t=tl(S(2), mark=lidx(S(2), '加 --as=alice', '--as=bob', 'system:masters'), done=lidx(S(2), '授予 impersonate', '模拟成功时')), kv=KV([['impersonate 动词', '对 users / groups / serviceaccounts 分别授权'], ['resourceNames', '可以限制只能模拟谁'], ['提权防线', '组也要单独授权,不能顺手带上']], ['impersonate 动词'])),
    step("给 caller 自己 edit 之后,它自己读 secrets 成功;但 caller 模拟 alice 读 secrets 仍是 Forbidden: User \"alice\" cannot list resource \"secrets\" …——模拟之后用的是 alice 的权限,caller 自己的权限不会叠加进来。管理员用 kubectl auth can-i --list --as=alice 可以列出 alice 在该命名空间能做的 81 行。", f=fl(F3, cur=[1], done=[0, 2]), t=tl(S(3), mark=lidx(S(3), 'caller 模拟 alice 读 secrets', '但 caller 模拟 alice'), done=lidx(S(3), '给 caller 自己 edit', 'auth can-i --list')), kv=KV([['取被模拟者的', '模拟后只有 alice 的权限'], ['用途', '排查权限问题:以用户视角试一遍'], ['风险', 'impersonate 权限本身等于“成为任何人”']], ['取被模拟者的'])),
]
A = mkartk('k85', 85, 'Kubernetes,用户模拟,impersonation,RBAC,--as,真实验证,动画演示',
    '在 kind 集群里实测用户模拟:管理员 kubectl --as=alice 按 alice 的权限鉴权(绑定 view 前 Forbidden、后成功),--as-group 补充组并自动带上 system:authenticated,不写 --as 时 kubectl 直接拒绝;ServiceAccount 想模拟别人必须有 impersonate 权限,可以用 resourceNames 限制到 alice,模拟 bob 或借 system:masters 组都被拒;模拟之后只剩被模拟者的权限,不会叠加自己的。',
    '--as 是怎么实现的?谁有资格模拟别人?能不能顺便把自己的权限也带上?借一个高权限的组会怎样?这篇用管理员和一个只有 view 的 ServiceAccount 把模拟的权限边界逐项验证一遍。',
    [('--as', '请求里带 Impersonate-User 头,服务端按被模拟者鉴权'), ('resourceNames: [alice]', '把 impersonate 权限限制到只能模拟 alice,模拟 bob 或带 system:masters 组都被拒'), ('不叠加', '模拟之后只用被模拟者的权限,模拟者自己的权限不起作用')],
    [('管理员模拟', '<p>管理员 <code>kubectl get pods --as=alice</code>:alice 没有任何权限,返回 <code>Forbidden: User "alice" cannot list resource "pods" …</code>;给 alice 绑定 <code>view</code> 之后成功,但访问 <code>default</code> 命名空间仍被拒。<code>kubectl auth whoami --as=alice --as-group=dev --as-group=ops</code> 得到 <code>username=alice</code>、<code>groups=[dev, ops, system:authenticated]</code>(服务端补上 <code>system:authenticated</code>);加 <code>--as-uid</code>、<code>--as-user-extra</code> 得到对应的 uid 和 extra。只写 <code>--as-group</code> 不写 <code>--as</code> 会被 kubectl 直接拒绝(<code>without impersonating a user</code>)。</p>'),
     ('谁有资格模拟', '<p>ServiceAccount <code>caller</code>(只有 view)自己读 pods 没问题;加 <code>--as=alice</code> 被拒,消息里的动词是 <code>impersonate-on:user-info:list</code>(这是新版本里更细的模拟授权的写法,我没有深入验证它的语义)。给它一条 <code>impersonate</code> <code>users</code>(<code>resourceNames: [alice]</code>)的权限后,<code>--as=alice</code> 成功;换成 <code>--as=bob</code> 被拒(<code>users "bob" is forbidden … cannot impersonate resource "users"</code>);<code>--as=alice --as-group=system:masters</code> 也被拒(<code>groups "system:masters" is forbidden</code>)——组要单独授权,不能顺手带上。模拟成功时 whoami 看到的用户名是 alice,caller 自己的身份被替换而不是叠加。</p>'),
     ('只取被模拟者的权限', '<p>给 caller 自己 <code>edit</code> 之后,它自己读 secrets 成功;但 caller 模拟 alice 读 secrets 仍是 <code>Forbidden: User "alice" cannot list resource "secrets" …</code>——模拟之后用的是 alice 的权限,caller 自己的权限不会叠加。管理员用 <code>kubectl auth can-i --list --as=alice</code> 能列出 alice 在该命名空间能做的 81 行。排查“某个用户为什么没权限”时,以他的身份试一遍最直接;而 <code>impersonate</code> 权限本身就等于“可以成为任何被授权的人”,要谨慎授予。</p>')],
    steps,
    [ENV_K + '。三节点 kind 集群 kx-main(Kubernetes v1.37.0);“管理员”是 kind 生成的 kubeconfig 身份(system:masters);ServiceAccount 的令牌由 kubectl create token 生成,用 --server --token 访问;alice、bob 是不存在的用户名,只通过 RBAC 绑定定义权限;每种情形各一次',
     '没有验证:impersonate-on:* 这类细化动词的完整语义与启用条件;审计日志里 impersonatedUser 字段(需要审计策略,见 k18);通过 HTTP 头 Impersonate-Extra-* 传递更多属性;模拟 ServiceAccount(serviceaccounts 资源)的授权方式;kubeconfig 里写死 as 的做法'],
    '用户模拟', PANELS)
